package org.eclipse.rdf4j.query.algebra;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class QueryModelSerializationTest {
	@Test
	void repeatableValuesAlgebraTreeRoundTripsWithItsRowsAndParentLinks() throws Exception {
		MapBindingSet row = new MapBindingSet();
		row.addBinding("x", SimpleValueFactory.getInstance().createLiteral("value"));
		BindingSetAssignment values = new BindingSetAssignment();
		values.setDeclaredBindingNames(Set.of("x"));
		values.setBindingSets(List.of(row));
		QueryRoot original = new QueryRoot(new Join(values, new SingletonSet()));

		QueryRoot restored;
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
			output.writeObject(original);
		}
		try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			restored = (QueryRoot) input.readObject();
		}

		assertThat(restored).isEqualTo(original);
		Join restoredJoin = (Join) restored.getArg();
		assertSame(restored, restoredJoin.getParentNode());
		assertSame(restoredJoin, restoredJoin.getLeftArg().getParentNode());
		assertSame(restoredJoin, restoredJoin.getRightArg().getParentNode());
		assertThat(((BindingSetAssignment) restoredJoin.getLeftArg()).getBindingSets()).containsExactly(row);
	}
}
